{"version":3,"file":"core.cjs.production.min.js","sources":["../src/components/DndMonitor/context.ts","../src/components/DndMonitor/useDndMonitor.ts","../src/components/Accessibility/defaults.ts","../src/components/Accessibility/Accessibility.tsx","../src/store/actions.ts","../src/utilities/other/noop.ts","../src/utilities/coordinates/constants.ts","../src/utilities/coordinates/distanceBetweenPoints.ts","../src/utilities/coordinates/getRelativeTransformOrigin.ts","../src/utilities/algorithms/helpers.ts","../src/utilities/algorithms/closestCenter.ts","../src/utilities/algorithms/rectIntersection.ts","../src/utilities/algorithms/pointerWithin.ts","../src/utilities/rect/getRectDelta.ts","../src/utilities/rect/rectAdjustment.ts","../src/utilities/transform/parseTransform.ts","../src/utilities/rect/getRect.ts","../src/utilities/transform/inverseTransform.ts","../src/utilities/scroll/getScrollableAncestors.ts","../src/utilities/scroll/isScrollable.ts","../src/utilities/scroll/isFixed.ts","../src/utilities/scroll/getScrollableElement.ts","../src/utilities/scroll/getScrollCoordinates.ts","../src/types/direction.ts","../src/utilities/scroll/documentScrollingElement.ts","../src/utilities/scroll/getScrollPosition.ts","../src/utilities/scroll/getScrollDirectionAndSpeed.ts","../src/utilities/scroll/getScrollElementRect.ts","../src/utilities/scroll/getScrollOffsets.ts","../src/utilities/scroll/scrollIntoViewIfNeeded.ts","../src/utilities/rect/Rect.ts","../src/sensors/utilities/Listeners.ts","../src/sensors/utilities/hasExceededDistance.ts","../src/sensors/events.ts","../src/sensors/keyboard/types.ts","../src/sensors/keyboard/defaults.ts","../src/sensors/keyboard/KeyboardSensor.ts","../src/sensors/pointer/AbstractPointerSensor.ts","../src/sensors/utilities/getEventListenerTarget.ts","../src/sensors/pointer/PointerSensor.ts","../src/sensors/mouse/MouseSensor.ts","../src/sensors/touch/TouchSensor.ts","../src/hooks/utilities/useAutoScroller.ts","../src/hooks/utilities/useDroppableMeasuring.ts","../src/hooks/utilities/useInitialValue.ts","../src/hooks/utilities/useResizeObserver.ts","../src/hooks/utilities/useRect.ts","../src/hooks/utilities/useMutationObserver.ts","../src/hooks/utilities/useScrollableAncestors.ts","../src/hooks/utilities/useScrollOffsetsDelta.ts","../src/hooks/utilities/useWindowRect.ts","../src/utilities/rect/getWindowClientRect.ts","../src/hooks/utilities/useRects.ts","../src/utilities/nodes/getMeasurableNode.ts","../src/components/DndContext/defaults.ts","../src/store/constructors.ts","../src/store/context.ts","../src/store/reducer.ts","../src/components/Accessibility/components/RestoreFocus.tsx","../src/modifiers/applyModifiers.ts","../src/components/DndContext/DndContext.tsx","../src/components/DndMonitor/useDndMonitorProvider.tsx","../src/components/DndContext/hooks/useMeasuringConfiguration.ts","../src/hooks/utilities/useCachedNode.ts","../src/hooks/utilities/useInitialRect.ts","../src/components/DndContext/hooks/useLayoutShiftScrollCompensation.ts","../src/hooks/utilities/useDragOverlayMeasuring.ts","../src/hooks/utilities/useRectDelta.ts","../src/hooks/utilities/useScrollOffsets.ts","../src/utilities/rect/adjustScale.ts","../src/hooks/utilities/useCombineActivators.ts","../src/hooks/utilities/useSensorSetup.ts","../src/hooks/useDraggable.ts","../src/hooks/useDndContext.ts","../src/hooks/useDroppable.ts","../src/components/DragOverlay/components/AnimationManager/AnimationManager.tsx","../src/components/DragOverlay/components/NullifiedContextProvider/NullifiedContextProvider.tsx","../src/components/DragOverlay/components/PositionedOverlay/PositionedOverlay.tsx","../src/components/DragOverlay/hooks/useDropAnimation.ts","../src/components/DragOverlay/hooks/useKey.ts","../src/components/DragOverlay/DragOverlay.tsx","../src/utilities/algorithms/closestCorners.ts","../src/hooks/utilities/useSyntheticListeners.ts","../src/sensors/useSensor.ts","../src/sensors/useSensors.ts"],"sourcesContent":["import {createContext} from 'react';\n\nimport type {RegisterListener} from './types';\n\nexport const DndMonitorContext = createContext<RegisterListener | null>(null);\n","import {useContext, useEffect} from 'react';\n\nimport {DndMonitorContext} from './context';\nimport type {DndMonitorListener} from './types';\n\nexport function useDndMonitor(listener: DndMonitorListener) {\n  const registerListener = useContext(DndMonitorContext);\n\n  useEffect(() => {\n    if (!registerListener) {\n      throw new Error(\n        'useDndMonitor must be used within a children of <DndContext>'\n      );\n    }\n\n    const unsubscribe = registerListener(listener);\n\n    return unsubscribe;\n  }, [listener, registerListener]);\n}\n","import type {Announcements, ScreenReaderInstructions} from './types';\n\nexport const defaultScreenReaderInstructions: ScreenReaderInstructions = {\n  draggable: `\n    To pick up a draggable item, press the space bar.\n    While dragging, use the arrow keys to move the item.\n    Press space again to drop the item in its new position, or press escape to cancel.\n  `,\n};\n\nexport const defaultAnnouncements: Announcements = {\n  onDragStart({active}) {\n    return `Picked up draggable item ${active.id}.`;\n  },\n  onDragOver({active, over}) {\n    if (over) {\n      return `Draggable item ${active.id} was moved over droppable area ${over.id}.`;\n    }\n\n    return `Draggable item ${active.id} is no longer over a droppable area.`;\n  },\n  onDragEnd({active, over}) {\n    if (over) {\n      return `Draggable item ${active.id} was dropped over droppable area ${over.id}`;\n    }\n\n    return `Draggable item ${active.id} was dropped.`;\n  },\n  onDragCancel({active}) {\n    return `Dragging was cancelled. Draggable item ${active.id} was dropped.`;\n  },\n};\n","import React, {useEffect, useMemo, useState} from 'react';\nimport {createPortal} from 'react-dom';\nimport {useUniqueId} from '@dnd-kit/utilities';\nimport {HiddenText, LiveRegion, useAnnouncement} from '@dnd-kit/accessibility';\n\nimport {DndMonitorListener, useDndMonitor} from '../DndMonitor';\n\nimport type {Announcements, ScreenReaderInstructions} from './types';\nimport {\n  defaultAnnouncements,\n  defaultScreenReaderInstructions,\n} from './defaults';\n\ninterface Props {\n  announcements?: Announcements;\n  container?: Element;\n  screenReaderInstructions?: ScreenReaderInstructions;\n  hiddenTextDescribedById: string;\n}\n\nexport function Accessibility({\n  announcements = defaultAnnouncements,\n  container,\n  hiddenTextDescribedById,\n  screenReaderInstructions = defaultScreenReaderInstructions,\n}: Props) {\n  const {announce, announcement} = useAnnouncement();\n  const liveRegionId = useUniqueId(`DndLiveRegion`);\n  const [mounted, setMounted] = useState(false);\n\n  useEffect(() => {\n    setMounted(true);\n  }, []);\n\n  useDndMonitor(\n    useMemo<DndMonitorListener>(\n      () => ({\n        onDragStart({active}) {\n          announce(announcements.onDragStart({active}));\n        },\n        onDragMove({active, over}) {\n          if (announcements.onDragMove) {\n            announce(announcements.onDragMove({active, over}));\n          }\n        },\n        onDragOver({active, over}) {\n          announce(announcements.onDragOver({active, over}));\n        },\n        onDragEnd({active, over}) {\n          announce(announcements.onDragEnd({active, over}));\n        },\n        onDragCancel({active, over}) {\n          announce(announcements.onDragCancel({active, over}));\n        },\n      }),\n      [announce, announcements]\n    )\n  );\n\n  if (!mounted) {\n    return null;\n  }\n\n  const markup = (\n    <>\n      <HiddenText\n        id={hiddenTextDescribedById}\n        value={screenReaderInstructions.draggable}\n      />\n      <LiveRegion id={liveRegionId} announcement={announcement} />\n    </>\n  );\n\n  return container ? createPortal(markup, container) : markup;\n}\n","import type {Coordinates, UniqueIdentifier} from '../types';\nimport type {DroppableContainer} from './types';\n\nexport enum Action {\n  DragStart = 'dragStart',\n  DragMove = 'dragMove',\n  DragEnd = 'dragEnd',\n  DragCancel = 'dragCancel',\n  DragOver = 'dragOver',\n  RegisterDroppable = 'registerDroppable',\n  SetDroppableDisabled = 'setDroppableDisabled',\n  UnregisterDroppable = 'unregisterDroppable',\n}\n\nexport type Actions =\n  | {\n      type: Action.DragStart;\n      active: UniqueIdentifier;\n      initialCoordinates: Coordinates;\n    }\n  | {type: Action.DragMove; coordinates: Coordinates}\n  | {type: Action.DragEnd}\n  | {type: Action.DragCancel}\n  | {\n      type: Action.RegisterDroppable;\n      element: DroppableContainer;\n    }\n  | {\n      type: Action.SetDroppableDisabled;\n      id: UniqueIdentifier;\n      key: UniqueIdentifier;\n      disabled: boolean;\n    }\n  | {\n      type: Action.UnregisterDroppable;\n      id: UniqueIdentifier;\n      key: UniqueIdentifier;\n    };\n","export function noop(..._args: any) {}\n","import type {Coordinates} from '../../types';\n\nexport const defaultCoordinates: Coordinates = Object.freeze({\n  x: 0,\n  y: 0,\n});\n","import type {Coordinates} from '../../types';\n\n/**\n * Returns the distance between two points\n */\nexport function distanceBetween(p1: Coordinates, p2: Coordinates) {\n  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));\n}\n","import {getEventCoordinates} from '@dnd-kit/utilities';\nimport type {ClientRect} from '../../types';\n\nexport function getRelativeTransformOrigin(\n  event: MouseEvent | TouchEvent | KeyboardEvent,\n  rect: ClientRect\n) {\n  const eventCoordinates = getEventCoordinates(event);\n\n  if (!eventCoordinates) {\n    return '0 0';\n  }\n\n  const transformOrigin = {\n    x: ((eventCoordinates.x - rect.left) / rect.width) * 100,\n    y: ((eventCoordinates.y - rect.top) / rect.height) * 100,\n  };\n\n  return `${transformOrigin.x}% ${transformOrigin.y}%`;\n}\n","/* eslint-disable no-redeclare */\nimport type {ClientRect} from '../../types';\n\nimport type {Collision, CollisionDescriptor} from './types';\n\n/**\n * Sort collisions from smallest to greatest value\n */\nexport function sortCollisionsAsc(\n  {data: {value: a}}: CollisionDescriptor,\n  {data: {value: b}}: CollisionDescriptor\n) {\n  return a - b;\n}\n\n/**\n * Sort collisions from greatest to smallest value\n */\nexport function sortCollisionsDesc(\n  {data: {value: a}}: CollisionDescriptor,\n  {data: {value: b}}: CollisionDescriptor\n) {\n  return b - a;\n}\n\n/**\n * Returns the coordinates of the corners of a given rectangle:\n * [TopLeft {x, y}, TopRight {x, y}, BottomLeft {x, y}, BottomRight {x, y}]\n */\nexport function cornersOfRectangle({left, top, height, width}: ClientRect) {\n  return [\n    {\n      x: left,\n      y: top,\n    },\n    {\n      x: left + width,\n      y: top,\n    },\n    {\n      x: left,\n      y: top + height,\n    },\n    {\n      x: left + width,\n      y: top + height,\n    },\n  ];\n}\n\n/**\n * Returns the first collision, or null if there isn't one.\n * If a property is specified, returns the specified property of the first collision.\n */\nexport function getFirstCollision(\n  collisions: Collision[] | null | undefined\n): Collision | null;\nexport function getFirstCollision<T extends keyof Collision>(\n  collisions: Collision[] | null | undefined,\n  property: T\n): Collision[T] | null;\nexport function getFirstCollision(\n  collisions: Collision[] | null | undefined,\n  property?: keyof Collision\n) {\n  if (!collisions || collisions.length === 0) {\n    return null;\n  }\n\n  const [firstCollision] = collisions;\n\n  return property ? firstCollision[property] : firstCollision;\n}\n","import {distanceBetween} from '../coordinates';\nimport type {Coordinates, ClientRect} from '../../types';\n\nimport type {CollisionDescriptor, CollisionDetection} from './types';\nimport {sortCollisionsAsc} from './helpers';\n\n/**\n * Returns the coordinates of the center of a given ClientRect\n */\nfunction centerOfRectangle(\n  rect: ClientRect,\n  left = rect.left,\n  top = rect.top\n): Coordinates {\n  return {\n    x: left + rect.width * 0.5,\n    y: top + rect.height * 0.5,\n  };\n}\n\n/**\n * Returns the closest rectangles from an array of rectangles to the center of a given\n * rata.uniforms[ name ] = {
  					type: 't',
  					value: value.toJSON( meta ).uuid
  				};

  			} else if ( value && value.isColor ) {

  				data.uniforms[ name ] = {
  					type: 'c',
  					value: value.getHex()
  				};

  			} else if ( value && value.isVector2 ) {

  				data.uniforms[ name ] = {
  					type: 'v2',
  					value: value.toArray()
  				};

  			} else if ( value && value.isVector3 ) {

  				data.uniforms[ name ] = {
  					type: 'v3',
  					value: value.toArray()
  				};

  			} else if ( value && value.isVector4 ) {

  				data.uniforms[ name ] = {
  					type: 'v4',
  					value: value.toArray()
  				};

  			} else if ( value && value.isMatrix3 ) {

  				data.uniforms[ name ] = {
  					type: 'm3',
  					value: value.toArray()
  				};

  			} else if ( value && value.isMatrix4 ) {

  				data.uniforms[ name ] = {
  					type: 'm4',
  					value: value.toArray()
  				};

  			} else {

  				data.uniforms[ name ] = {
  					value: value
  				};

  				// note: the array variants v2v, v3v, v4v, m4v and tv are not supported so far

  			}

  		}

  		if ( Object.keys( this.defines ).length > 0 ) data.defines = this.defines;

  		data.vertexShader = this.vertexShader;
  		data.fragmentShader = this.fragmentShader;

  		data.lights = this.lights;
  		data.clipping = this.clipping;

  		const extensions = {};

  		for ( const key in this.extensions ) {

  			if ( this.extensions[ key ] === true ) extensions[ key ] = true;

  		}

  		if ( Object.keys( extensions ).length > 0 ) data.extensions = extensions;

  		return data;

  	}

  }

  /**
   * This class works just like {@link ShaderMaterial}, except that definitions
   * of built-in uniforms and attributes are not automatically prepended to the
   * GLSL shader code.
   *
   * `RawShaderMaterial` can only be used with {@link WebGLRenderer}.
   *
   * @augments ShaderMaterial
   */
  class RawShaderMaterial extends ShaderMaterial {

  	/**
  	 * Constructs a new raw shader material.
  	 *
  	 * @param {Object} [parameters] - An object with one or more properties
  	 * defining the material's appearance. Any property of the material
  	 * (including any property from inherited materials) can be passed
  	 * in here. Color values can be passed any type of value accepted
  	 * by {@link Color#set}.
  	 */
  	constructor( parameters ) {

  		super( parameters );

  		/**
  		 * This flag can be used for type testing.
  		 *
  		 * @type {boolean}
  		 * @readonly
  		 * @default true
  		 */
  		this.isRawShaderMaterial = true;

  		this.type = 'RawShaderMaterial';

  	}

  }

  /**
   * A standard physically based material, using Metallic-Roughness workflow.
   *
   * Physically based rendering (PBR) has recently become the standard in many
   * 3D applications, such as [Unity](https://blogs.unity3d.com/2014/10/29/physically-based-shading-in-unity-5-a-primer/),
   * [Unreal](https://docs.unrealengine.com/latest/INT/Engine/Rendering/Materials/PhysicallyBased/) and
   * [3D Studio Max](http://area.autodesk.com/blogs/the-3ds-max-blog/what039s-new-for-rendering-in-3ds-max-2017).
   *
   * This approach differs from older approaches in that instead of using
   * approximations for the way in which light interacts with a surface, a
   * physically correct model is used. The idea is that, instead of tweaking
   * materials to look good under specific lighting, a material can be created
   * that will react 'correctly' under all lighting scenarios.
   *
   * In practice this gives a more accurate and realistic looking result than
   * the {@link MeshLambertMaterial} or {@link MeshPhongMaterial}, at the cost of
   * being somewhat more computationally expensive. `MeshStandardMaterial` uses per-fragment
   * shading.
   *
   * Note that for best results you should always specify an environment map when using this material.
   *
   * For a non-technical introduction to the concept of PBR and how to set up a
   * PBR material, check out these articles by the people at [marmoset](https://www.marmoset.co):
   *
   * - [Basic Theory of Physically Based Rendering](https://www.marmoset.co/posts/basic-theory-of-physically-based-rendering/)
   * - [Physically Based Rendering and You Can Too](https://www.marmoset.co/posts/physically-based-rendering-and-you-can-too/)
   *
   * Technical details of the approach used in three.js (and most other PBR systems) can be found is this
   * [paper from Disney](https://media.disneyanimation.com/uploads/production/publication_asset/48/asset/s2012_pbs_disney_brdf_notes_v3.pdf)
   * (pdf), by Brent Burley.
   *
   * @augments Material
   * @demo scenes/material-browser.html#MeshStandardMaterial
   */
  class MeshStandardMaterial extends Material {

  	/**
  	 * Constructs a new mesh standard material.
  	 *
  	 * @param {Object} [parameters] - An object with one or more properties
  	 * defining the material's appearance. Any property of the material
  	 * (including any property from inherited materials) can be passed
  	 * in here. Color values can be passed any type of value accepted
  	 * by {@link Color#set}.
  	 */
  	constructor( parameters ) {

  		super();

  		/**
  		 * This flag can be used for type testing.
  		 *
  		 * @type {boolean}
  		 * @readonly
  		 * @default true
  		 */
  		this.isMeshStandardMaterial = true;

  		this.type = 'MeshStandardMaterial';

  		this.defines = { 'STANDARD': '' };

  		/**
  		 * Color of the material.
  		 *
  		 * @type {Color}
  		 * @default (1,1,1)
  		 */
  		this.color = new Color$1( 0xffffff ); // diffuse

  		/**
  		 * How rough the material appears. `0.0` means a smooth mirror reflection, `1.0`
  		 * means fully diffuse. If `roughnessMap` is also provided,
  		 * both values are multiplied.
  		 *
  		 * @type {number}
  		 * @default 1
  		 */
  		this.roughness = 1.0;

  		/**
  		 * How much the material is like a metal. Non-metallic materials such as wood
  		 * or stone use `0.0`, metallic use `1.0`, with nothing (usually) in between.
  		 * A value between `0.0` and `1.0` could be used for a rusty metal look.
  		 * If `metalnessMap` is also provided, both values are multiplied.
  		 *
  		 * @type {number}
  		 * @default 0
  		 */
  		this.metalness = 0.0;

  		/**
  		 * The color map. May optionally include an alpha channel, typically combined
  		 * with {@link Material#transparent} or {@link Material#alphaTest}. The texture map
  		 * color is modulated by the diffuse `color`.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.map = null;

  		/**
  		 * The light map. Requires a second set of UVs.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.lightMap = null;

  		/**
  		 * Intensity of the baked light.
  		 *
  		 * @type {number}
  		 * @default 1
  		 */
  		this.lightMapIntensity = 1.0;

  		/**
  		 * The red channel of this texture is used as the ambient occlusion map.
  		 * Requires a second set of UVs.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.aoMap = null;

  		/**
  		 * Intensity of the ambient occlusion effect. Range is `[0,1]`, where `0`
  		 * disables ambient occlusion. Where intensity is `1` and the AO map's
  		 * red channel is also `1`, ambient light is fully occluded on a surface.
  		 *
  		 * @type {number}
  		 * @default 1
  		 */
  		this.aoMapIntensity = 1.0;

  		/**
  		 * Emissive (light) color of the material, essentially a solid color
  		 * unaffected by other lighting.
  		 *
  		 * @type {Color}
  		 * @default (0,0,0)
  		 */
  		this.emissive = new Color$1( 0x000000 );

  		/**
  		 * Intensity of the emissive light. Modulates the emissive color.
  		 *
  		 * @type {number}
  		 * @default 1
  		 */
  		this.emissiveIntensity = 1.0;

  		/**
  		 * Set emissive (glow) map. The emissive map color is modulated by the
  		 * emissive color and the emissive intensity. If you have an emissive map,
  		 * be sure to set the emissive color to something other than black.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.emissiveMap = null;

  		/**
  		 * The texture to create a bump map. The black and white values map to the
  		 * perceived depth in relation to the lights. Bump doesn't actually affect
  		 * the geometry of the object, only the lighting. If a normal map is defined
  		 * this will be ignored.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.bumpMap = null;

  		/**
  		 * How much the bump map affects the material. Typical range is `[0,1]`.
  		 *
  		 * @type {number}
  		 * @default 1
  		 */
  		this.bumpScale = 1;

  		/**
  		 * The texture to create a normal map. The RGB values affect the surface
  		 * normal for each pixel fragment and change the way the color is lit. Normal
  		 * maps do not change the actual shape of the surface, only the lighting. In
  		 * case the material has a normal map authored using the left handed
  		 * convention, the `y` component of `normalScale` should be negated to compensate
  		 * for the different handedness.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.normalMap = null;

  		/**
  		 * The type of normal map.
  		 *
  		 * @type {(TangentSpaceNormalMap|ObjectSpaceNormalMap)}
  		 * @default TangentSpaceNormalMap
  		 */
  		this.normalMapType = TangentSpaceNormalMap;

  		/**
  		 * How much the normal map affects the material. Typical value range is `[0,1]`.
  		 *
  		 * @type {Vector2}
  		 * @default (1,1)
  		 */
  		this.normalScale = new Vector2( 1, 1 );

  		/**
  		 * The displacement map affects the position of the mesh's vertices. Unlike
  		 * other maps which only affect the light and shade of the material the
  		 * displaced vertices can cast shadows, block other objects, and otherwise
  		 * act as real geometry. The displacement texture is an image where the value
  		 * of each pixel (white being the highest) is mapped against, and
  		 * repositions, the vertices of the mesh.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.displacementMap = null;

  		/**
  		 * How much the displacement map affects the mesh (where black is no
  		 * displacement, and white is maximum displacement). Without a displacement
  		 * map set, this value is not applied.
  		 *
  		 * @type {number}
  		 * @default 0
  		 */
  		this.displacementScale = 1;

  		/**
  		 * The offset of the displacement map's values on the mesh's vertices.
  		 * The bias is added to the scaled sample of the displacement map.
  		 * Without a displacement map set, this value is not applied.
  		 *
  		 * @type {number}
  		 * @default 0
  		 */
  		this.displacementBias = 0;

  		/**
  		 * The green channel of this texture is used to alter the roughness of the
  		 * material.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.roughnessMap = null;

  		/**
  		 * The blue channel of this texture is used to alter the metalness of the
  		 * material.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.metalnessMap = null;

  		/**
  		 * The alpha map is a grayscale texture that controls the opacity across the
  		 * surface (black: fully transparent; white: fully opaque).
  		 *
  		 * Only the color of the texture is used, ignoring the alpha channel if one
  		 * exists. For RGB and RGBA textures, the renderer will use the green channel
  		 * when sampling this texture due to the extra bit of precision provided for
  		 * green in DXT-compressed and uncompressed RGB 565 formats. Luminance-only and
  		 * luminance/alpha textures will also still work as expected.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.alphaMap = null;

  		/**
  		 * The environment map. To ensure a physically correct rendering, environment maps
  		 * are internally pre-processed with {@link PMREMGenerator}.
  		 *
  		 * @type {?Texture}
  		 * @default null
  		 */
  		this.envMap = null;

  		/**
  		 * The rotation of the environment map in radians.
  		 *
  		 * @type {Euler}
  		 * @default (0,0,0)
  		 */
  		this.envMapRotation = new Euler();

  		/**
  		 * Scales the effect of the environment map by multiplying its color.
  		 *
  		 * @type {number}
  		 * @default 1
  		 */
  		this.envMapIntensity = 1.0;

  		/**
